using FluentValidation; using JTradeERP.Application.Common.Exceptions; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Security; using JTradeERP.Domain.Security; using MediatR;
namespace JTradeERP.Application.Features.Security.Administration.CreateUser;
public sealed record CreateUserCommand(string UserName,string Email,string Password):IRequest<CreateUserResponse>;
public sealed record CreateUserResponse(Guid Id,string UserName,string Email,bool IsActive);
public sealed class CreateUserValidator:AbstractValidator<CreateUserCommand>{public CreateUserValidator(){RuleFor(x=>x.UserName).NotEmpty().MaximumLength(100);RuleFor(x=>x.Email).NotEmpty().EmailAddress().MaximumLength(320);RuleFor(x=>x.Password).NotEmpty();}}
public sealed class CreateUserHandler(IApplicationDbContext db,IPasswordService passwords,ICurrentUserService actor):IRequestHandler<CreateUserCommand,CreateUserResponse>{public async Task<CreateUserResponse> Handle(CreateUserCommand r,CancellationToken ct){if(db.Users.Any(x=>x.UserName==r.UserName.Trim()||x.Email==r.Email.Trim()))throw new ConflictException("Username or email already exists.");var u=new User(r.UserName,r.Email,passwords.Hash(r.Password));db.Add(u);SecurityAuditWriter.Add(db,actor.UserId,"UserCreated","User",u.Id.ToString(),null,$"{u.UserName}|{u.Email}");await db.SaveChangesAsync(ct);return new(u.Id,u.UserName,u.Email,u.IsActive);}}
public static class CreateUserEndpoint{public static void Map(IEndpointRouteBuilder e)=>e.MapPost("/users",async(CreateUserCommand c,ISender s,CancellationToken t)=>Results.Created($"/api/admin/users",await s.Send(c,t))).RequirePermission("Admin.Users.Manage",Capability.Full);}
